llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Asciminib, a close analogue sharing the amide-linked trifluoromethoxyphenyl and aminopyridine/heterocycle motif, has an absolute oral bioavailability of approximately 73% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Esaxerenone, which shares the methyl-substituted benzamide-arylamine core and ortho-aryl substitution, shows about 89-90% absolute oral bioavailability in healthy subjects, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Leflunomide, an amide with a trifluoromethyl-substituted aromatic ring, reaches up to 80% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Conivaptan, an amide-containing heterocyclic drug, has an absolute oral bioavailability of 44% in humans, above the 20% threshold and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Netupitant, which contains amide, trifluoromethyl, and piperazine-like features, has a high absolute bioavailability of 63-87% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Pretomanid, containing a trifluoromethoxyphenyl group, shows high and dose-proportional oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Sorafenib, despite some structural overlap, has a reported oral bioavailability of approximately 8.5% in one human study, which would be low; however, other human reports give 38-49%, and the low similarity limits transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C35"],
      "claim": "ABT-384, with amide and CF3-pyridine/piperazine features, has a model-estimated bioavailability of 18.1%, just below the 20% threshold, providing weak contradictory evidence due to low structural similarity.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence from structurally related amide/heteroaryl drugs (asciminib ~73%, esaxerenone ~90%, leflunomide ~80%, conivaptan 44%, netupitant 63-87%) supports F >=20%. Low-F analogues are less similar or conflicted, so the query is predicted high.",
  "evidence_gaps": [
    "No direct experimental bioavailability data are available for the query molecule.",
    "All retrieved analogues have low Morgan similarity (0.23-0.31), limiting quantitative transferability.",
    "Sorafenib records conflict (8.5% vs 38-49%), introducing uncertainty about possible low-F liabilities."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

